db:note.db:programlisting:
// Connect using qOverload:
connect(sender, &SenderClass::signal,
        testClass, qOverload<double>(&TestClass::setValue));

// Or using a lambda as wrapper:
connect(sender, &SenderClass::signal,
        testClass, [receiver = testClass](double value) { receiver->setValue(value); });

// Connect using qOverload:
connect(sender, &SenderClass::signal,
        testClass, qOverload<int>(&TestClass::setValue));

// Or using a lambda as wrapper:
connect(sender, &SenderClass::signal,
        testClass, [receiver = testClass](int value) { receiver->setValue(value); });

// Connect using qOverload:
connect(testClass, qOverload<double>(&TestClass::valueChanged),
        receiver, &ReceiverClass::slot);

// Or using a lambda:
connect(testClass, qOverload<double>(&TestClass::valueChanged),
        this, [](double value) { /* handle valueChanged */ });

// Connect using qOverload:
connect(testClass, qOverload<int>(&TestClass::valueChanged),
        receiver, &ReceiverClass::slot);

// Or using a lambda:
connect(testClass, qOverload<int>(&TestClass::valueChanged),
        this, [](int value) { /* handle valueChanged */ });
